/** Answer-key helpers — shapes must match apps/assessment-service graders. */
const mc = (question, options, explanation, points = 1) => ({
  type: 'multiple_choice',
  question,
  options, // [answer, isCorrect][]
  explanation,
  points,
});
const numeric = (
  question,
  value,
  explanation,
  { tolerance = 0.01, points = 2 } = {},
) => ({
  type: 'numeric',
  question,
  correctAnswer: { value, tolerance },
  explanation,
  points,
});
const trueFalse = (question, value, explanation, points = 1) => ({
  type: 'true_false',
  question,
  correctAnswer: { value },
  explanation,
  points,
});
const fillBlank = (question, accepted, explanation, points = 2) => ({
  type: 'fill_blank',
  question,
  correctAnswer: { accepted },
  explanation,
  points,
});

