      content: `## រូបមន្ត​អាំងតេក្រាល​ដោយ​ផ្នែក

ចេញ​ពី​វិធាន​ផលគុណ​នៃ​ដេរីវេ គេ​ទទួល៖

$$
\\int u\\,dv = u v - \\int v\\,du
$$

គេ​ជ្រើស $u$ (ដែល​ដេរីវេ​ធ្វើ​ឲ្យ​សាមញ្ញ) និង $dv$ (ដែល​អាំងតេក្រាល​បាន​ងាយ)។ វិធាន **LIATE** ជួយ​ជ្រើស $u$៖ Logarithme, Inverse-trig, Algébrique, Trig, Exponentielle។

## ឧទាហរណ៍​គំរូ

$$
\\int x e^{x}\\,dx
$$

យក $u = x$ ($du = dx$), $dv = e^{x}dx$ ($v = e^{x}$)៖

$$
\\int x e^{x}\\,dx = x e^{x} - \\int e^{x}\\,dx = x e^{x} - e^{x} + C = (x-1)e^{x} + C
$$

## ឧទាហរណ៍​ដោះស្រាយ

**ឧទាហរណ៍ ១៖** $\\int x\\ln x\\,dx$៖ $u=\\ln x, dv=x\\,dx$ ⟹ $\\dfrac{x^{2}}{2}\\ln x - \\dfrac{x^{2}}{4} + C$។

**ឧទាហរណ៍ ២៖** $\\int x\\cos x\\,dx = x\\sin x + \\cos x + C$។

**ឧទាហរណ៍ ៣៖** $\\int x\\sin x\\,dx = -x\\cos x + \\sin x + C$។

**ឧទាហរណ៍ ៤៖** $\\int \\ln x\\,dx$៖ $u=\\ln x, dv=dx$ ⟹ $x\\ln x - x + C$។

**ឧទាហរណ៍ ៥៖** $\\int x e^{2x}\\,dx = \\dfrac{x}{2}e^{2x} - \\dfrac{1}{4}e^{2x} + C$។

**ឧទាហរណ៍ ៦៖** $\\int x^{2}e^{x}\\,dx$៖ ពីរ​ដង ⟹ $(x^{2}-2x+2)e^{x} + C$។

**ឧទាហរណ៍ ៧៖** $\\int_{0}^{1} x e^{x}\\,dx = [(x-1)e^{x}]_{0}^{1} = 0 - (-1) = 1$។

**ឧទាហរណ៍ ៨៖** $\\int \\ln x\\,dx$ លើ $[1, e]$៖ $[x\\ln x - x]_{1}^{e} = (e - e) - (0 - 1) = 1$។

## លំហាត់​អនុវត្ត

**លំហាត់ ១៖** $\\int x e^{x}\\,dx$។ **ដំណោះស្រាយ៖** $(x-1)e^{x}+C$។

**លំហាត់ ២៖** $\\int \\ln x\\,dx$។ **ដំណោះស្រាយ៖** $x\\ln x - x + C$។

**លំហាត់ ៣៖** $\\int x\\cos x\\,dx$។ **ដំណោះស្រាយ៖** $x\\sin x + \\cos x + C$។

**លំហាត់ ៤៖** $\\int x\\sin x\\,dx$។ **ដំណោះស្រាយ៖** $-x\\cos x + \\sin x + C$។

**លំហាត់ ៥៖** $\\int x\\ln x\\,dx$។ **ដំណោះស្រាយ៖** $\\frac{x^{2}}{2}\\ln x - \\frac{x^{2}}{4} + C$។

**លំហាត់ ៦៖** $\\int x e^{3x}\\,dx$។ **ដំណោះស្រាយ៖** $\\frac{x}{3}e^{3x} - \\frac{1}{9}e^{3x} + C$។

**លំហាត់ ៧៖** $\\int_{0}^{1} x e^{x}\\,dx$។ **ដំណោះស្រាយ៖** $1$។

**លំហាត់ ៨៖** $\\int_{1}^{e}\\ln x\\,dx$។ **ដំណោះស្រាយ៖** $1$។

**លំហាត់ ៩៖** $\\int 2x e^{x}\\,dx$។ **ដំណោះស្រាយ៖** $2(x-1)e^{x} + C$។

**លំហាត់ ១០៖** តើ​វិធាន​ណា​ជួយ​ជ្រើស $u$? **ដំណោះស្រាយ៖** LIATE។

### ចំណុច​សំខាន់​ត្រូវ​ចង​ចាំ

- $\\int u\\,dv = uv - \\int v\\,du$។
- ជ្រើស $u$ តាម LIATE (Log, Inverse-trig, Algébrique, Trig, Exp)។
- ពេល​ខ្លះ​ត្រូវ​អនុវត្ត​ពីរ​ដង (ឧ. $x^{2}e^{x}$)។`,
