      content: `## បំបែក​ជា​ប្រភាគ​សាមញ្ញ

ដើម្បី​អាំងតេក្រាល​ប្រភាគ​សនិទាន គេ​បំបែក​វា​ជា​ផលបូក​នៃ​ប្រភាគ​សាមញ្ញ។ **ឧទាហរណ៍​គំរូ៖**

$$
\\frac{1}{(x-1)(x-2)} = \\frac{A}{x-1} + \\frac{B}{x-2}
$$

គុណ​ចេញ៖ $1 = A(x-2) + B(x-1)$។ ជំនួស $x=1$៖ $A=-1$; $x=2$៖ $B=1$។ ដូច្នេះ៖

$$
\\int \\frac{dx}{(x-1)(x-2)} = -\\ln|x-1| + \\ln|x-2| + C = \\ln\\left|\\frac{x-2}{x-1}\\right| + C
$$

## ឧទាហរណ៍​ដោះស្រាយ

**ឧទាហរណ៍ ១៖** $\\dfrac{1}{x(x+1)} = \\dfrac{1}{x} - \\dfrac{1}{x+1}$ ⟹ $\\int = \\ln\\left|\\dfrac{x}{x+1}\\right| + C$។

**ឧទាហរណ៍ ២៖** $\\dfrac{5}{(x-2)(x+3)} = \\dfrac{1}{x-2} - \\dfrac{1}{x+3}$។

**ឧទាហរណ៍ ៣៖** $\\int\\dfrac{dx}{x^{2}-1}$៖ $\\dfrac{1}{(x-1)(x+1)}=\\dfrac{1/2}{x-1}-\\dfrac{1/2}{x+1}$ ⟹ $\\dfrac{1}{2}\\ln\\left|\\dfrac{x-1}{x+1}\\right|+C$។

**ឧទាហរណ៍ ៤៖** $\\dfrac{x}{(x+1)(x+2)}=\\dfrac{-1}{x+1}+\\dfrac{2}{x+2}$។

**ឧទាហរណ៍ ៥៖** $\\int\\dfrac{2\\,dx}{x^{2}-4}=\\dfrac{1}{2}\\ln\\left|\\dfrac{x-2}{x+2}\\right|+C$។

**ឧទាហរណ៍ ៦៖** $\\dfrac{3}{x(x-3)}=\\dfrac{-1}{x}+\\dfrac{1}{x-3}$។

**ឧទាហរណ៍ ៧៖** $\\int_{3}^{4}\\dfrac{dx}{(x-1)(x-2)}=\\left[\\ln\\left|\\dfrac{x-2}{x-1}\\right|\\right]_{3}^{4}=\\ln\\dfrac{2}{3}-\\ln\\dfrac{1}{2}=\\ln\\dfrac{4}{3}$។

**ឧទាហរណ៍ ៨៖** $\\dfrac{1}{x^{2}+x}=\\dfrac{1}{x}-\\dfrac{1}{x+1}$។

## លំហាត់​អនុវត្ត

**លំហាត់ ១៖** បំបែក $\\dfrac{1}{x(x+1)}$។ **ដំណោះស្រាយ៖** $\\dfrac{1}{x}-\\dfrac{1}{x+1}$។

**លំហាត់ ២៖** $\\int\\dfrac{dx}{x(x+1)}$។ **ដំណោះស្រាយ៖** $\\ln\\left|\\dfrac{x}{x+1}\\right|+C$។

**លំហាត់ ៣៖** បំបែក $\\dfrac{1}{(x-1)(x+1)}$។ **ដំណោះស្រាយ៖** $\\dfrac{1/2}{x-1}-\\dfrac{1/2}{x+1}$។

**លំហាត់ ៤៖** $A$ ក្នុង $\\dfrac{1}{(x-1)(x-2)}=\\dfrac{A}{x-1}+\\dfrac{B}{x-2}$។ **ដំណោះស្រាយ៖** $A=-1$។

**លំហាត់ ៥៖** $B$ ក្នុង​លំហាត់​ខាង​លើ។ **ដំណោះស្រាយ៖** $B=1$។

**លំហាត់ ៦៖** $\\int\\dfrac{dx}{x^{2}-1}$។ **ដំណោះស្រាយ៖** $\\dfrac{1}{2}\\ln\\left|\\dfrac{x-1}{x+1}\\right|+C$។

**លំហាត់ ៧៖** បំបែក $\\dfrac{1}{x^{2}+x}$។ **ដំណោះស្រាយ៖** $\\dfrac{1}{x}-\\dfrac{1}{x+1}$។

**លំហាត់ ៨៖** $\\int\\dfrac{2\\,dx}{x^{2}-4}$។ **ដំណោះស្រាយ៖** $\\dfrac{1}{2}\\ln\\left|\\dfrac{x-2}{x+2}\\right|+C$។

**លំហាត់ ៩៖** បំបែក $\\dfrac{x}{(x+1)(x+2)}$។ **ដំណោះស្រាយ៖** $\\dfrac{-1}{x+1}+\\dfrac{2}{x+2}$។

**លំហាត់ ១០៖** $\\int_{3}^{4}\\dfrac{dx}{(x-1)(x-2)}$។ **ដំណោះស្រាយ៖** $\\ln\\dfrac{4}{3}$។

### ចំណុច​សំខាន់​ត្រូវ​ចង​ចាំ

- បំបែក​ជា $\\dfrac{A}{x-a}+\\dfrac{B}{x-b}$ រួច​រក $A, B$ ដោយ​ជំនួស។
- $\\int\\dfrac{dx}{x-a}=\\ln|x-a|+C$។
- ត្រួត​ពិនិត្យ​ដោយ​យក​ភាគ​រួម​វិញ។`,
