      minutes: 50,
      content: `## អថេរ​ចៃដន្យ

**អថេរ​ចៃដន្យ** $X$ ជា​អថេរ​ដែល​យក​តម្លៃ​លេខ​តាម​លទ្ធផល​នៃ​ពិសោធន៍​ចៃដន្យ។ **បំណែងចែក​ប្រូបាប** នៃ $X$ ផ្តល់​ប្រូបាប $P(X = x_i) = p_i$ សម្រាប់​តម្លៃ​នីមួយៗ ដោយ $\\sum p_i = 1$។

**ឧទាហរណ៍៖** គ្រាប់​ឡុកឡាក់​យុត្តិធម៌៖ $X$ ជា​លេខ​ដែល​ចេញ ⟹ $P(X = k) = \\dfrac{1}{6}$ សម្រាប់ $k = 1, \\dots, 6$។

\`\`\`graph
{
  "xRange": [0, 4],
  "yRange": [0, 0.6],
  "xLabel": "xᵢ",
  "yLabel": "P",
  "segments": [
    { "from": [1, 0], "to": [1, 0.2], "color": "violet" },
    { "from": [2, 0], "to": [2, 0.5], "color": "violet" },
    { "from": [3, 0], "to": [3, 0.3], "color": "violet" }
  ],
  "points": [
    { "x": 1, "y": 0.2, "color": "rose" },
    { "x": 2, "y": 0.5, "color": "rose" },
    { "x": 3, "y": 0.3, "color": "rose" }
  ],
  "caption": "បំណែងចែកប្រូបាបនៃ X៖ P(1)=0.2, P(2)=0.5, P(3)=0.3 (ផលបូក=1)"
}
\`\`\`

## សង្ឃឹម​គណិត (espérance)

$$
E(X) = \\sum_{i} x_i\\, p_i
$$

វា​ជា​តម្លៃ​មធ្យម​ដែល​រំពឹង​ទុក។

## វ៉ារ្យង់ និង​គម្លាត​គំរូ

$$
V(X) = \\sum_{i} (x_i - E(X))^{2}\\, p_i = E(X^{2}) - [E(X)]^{2} , \\qquad \\sigma(X) = \\sqrt{V(X)}
$$

## ឧទាហរណ៍​ដោះស្រាយ

**ឧទាហរណ៍ ១៖** $X$៖ $P(1)=0.2, P(2)=0.5, P(3)=0.3$។ $E(X) = 1(0.2) + 2(0.5) + 3(0.3) = 2.1$។

**ឧទាហរណ៍ ២៖** $E(X^{2}) = 1(0.2) + 4(0.5) + 9(0.3) = 4.9$; $V(X) = 4.9 - 2.1^{2} = 0.49$។

**ឧទាហរណ៍ ៣៖** $\\sigma(X) = \\sqrt{0.49} = 0.7$។

**ឧទាហរណ៍ ៤៖** គ្រាប់​ឡុកឡាក់៖ $E(X) = \\dfrac{1+2+\\dots+6}{6} = 3.5$។

**ឧទាហរណ៍ ៥៖** កាក់​យុត្តិធម៌ $X = $ ចំនួន​ក្បាល​ក្នុង​មួយ​បោះ ($0$ ឬ $1$)៖ $E(X) = 0.5$។

**ឧទាហរណ៍ ៦៖** $X$៖ $P(0)=0.5, P(10)=0.5$។ $E(X) = 5$; $V(X) = 0.5(0-5)^{2} + 0.5(10-5)^{2} = 25$។

**ឧទាហរណ៍ ៧៖** ល្បែង៖ ឈ្នះ $6$ ($p=\\frac{1}{4}$) ចាញ់ $2$ ($p=\\frac{3}{4}$)។ $E(\\text{gain}) = 6\\cdot\\frac{1}{4} - 2\\cdot\\frac{3}{4} = 0$ (យុត្តិធម៌)។

**ឧទាហរណ៍ ៨៖** $E(aX + b) = a E(X) + b$ (លីនេអ៊ែរីតេ)។

## លំហាត់​អនុវត្ត

**លំហាត់ ១៖** $P(1)=0.3, P(2)=0.7$។ $E(X)$? **ដំណោះស្រាយ៖** $0.3 + 1.4 = 1.7$។

**លំហាត់ ២៖** $P(0)=0.4, P(5)=0.6$។ $E(X)$? **ដំណោះស្រាយ៖** $3$។

**លំហាត់ ៣៖** $P(2)=0.5, P(4)=0.5$។ $V(X)$? **ដំណោះស្រាយ៖** $E=3$, $V = 0.5(1) + 0.5(1) = 1$។

**លំហាត់ ៤៖** គ្រាប់​ឡុកឡាក់ $E(X)$? **ដំណោះស្រាយ៖** $3.5$។

**លំហាត់ ៥៖** $P(1)=0.2,P(2)=0.3,P(3)=0.5$។ $E(X)$? **ដំណោះស្រាយ៖** $0.2+0.6+1.5 = 2.3$។

**លំហាត់ ៦៖** $\\sigma$ បើ $V(X)=0.64$? **ដំណោះស្រាយ៖** $0.8$។

**លំហាត់ ៧៖** កាក់ $E(X)$ (ក្បាល=1)? **ដំណោះស្រាយ៖** $0.5$។

**លំហាត់ ៨៖** $E(2X+3)$ បើ $E(X)=4$? **ដំណោះស្រាយ៖** $11$។

**លំហាត់ ៩៖** $P(0)=0.25,P(1)=0.5,P(2)=0.25$។ $E(X)$? **ដំណោះស្រាយ៖** $1$។

**លំហាត់ ១០៖** តើ $\\sum p_i$ ត្រូវ​ស្មើ​ប៉ុន្មាន? **ដំណោះស្រាយ៖** $1$។

### ចំណុច​សំខាន់​ត្រូវ​ចង​ចាំ

- $\\sum p_i = 1$; $E(X) = \\sum x_i p_i$។
- $V(X) = E(X^{2}) - [E(X)]^{2}$; $\\sigma = \\sqrt{V}$។
- $E(aX+b) = aE(X)+b$។`,
