      content: `## ការ​រាប់​មូលដ្ឋាន

**គោលការណ៍​គុណ៖** បើ​ដំណើរ​ការ​មួយ​មាន $m$ ជម្រើស រួច $n$ ជម្រើស នោះ​សរុប $m \\times n$ លទ្ធផល។

**ហ្វាក់តូរីយែល៖** $n! = n(n-1)(n-2)\\cdots 2\\cdot 1$; $0! = 1$។

## អារ៉ង់ស្ម៉ង់ (permutations/arrangements)

ចំនួន​វិធី​តម្រៀប $k$ ធាតុ​ក្នុង​ចំណោម $n$ (លំដាប់​សំខាន់)៖

$$
A_n^{k} = \\frac{n!}{(n-k)!}
$$

## គំបីណេហ្សុង (combinaisons)

ចំនួន​វិធី​ជ្រើស $k$ ធាតុ​ក្នុង​ចំណោម $n$ (លំដាប់​មិន​សំខាន់)៖

$$
C_n^{k} = \\binom{n}{k} = \\frac{n!}{k!(n-k)!}
$$

លក្ខណៈ៖ $\\dbinom{n}{k} = \\dbinom{n}{n-k}$ និង $\\dbinom{n}{0} = \\dbinom{n}{n} = 1$។

## ឧទាហរណ៍​ដោះស្រាយ

**ឧទាហរណ៍ ១៖** $5! = 120$។

**ឧទាហរណ៍ ២៖** $A_5^{2} = \\dfrac{5!}{3!} = 20$។

**ឧទាហរណ៍ ៣៖** $C_5^{2} = \\dfrac{5!}{2!\\,3!} = 10$។

**ឧទាហរណ៍ ៤៖** ចំនួន​វិធី​តម្រៀប $4$ សៀវភៅ៖ $4! = 24$។

**ឧទាហរណ៍ ៥៖** ជ្រើស​ក្រុម $3$ នាក់​ក្នុង​ចំណោម $10$៖ $C_{10}^{3} = 120$។

**ឧទាហរណ៍ ៦៖** $\\dbinom{7}{5} = \\dbinom{7}{2} = 21$។

**ឧទាហរណ៍ ៧៖** ចំនួន​លេខ​កូដ ៣ ខ្ទង់​ផ្សេង​គ្នា​ពី $0$–$9$៖ $A_{10}^{3} = 720$។

**ឧទាហរណ៍ ៨៖** $\\dbinom{6}{0} + \\dbinom{6}{6} = 2$។

## លំហាត់​អនុវត្ត

**លំហាត់ ១៖** $6!$។ **ដំណោះស្រាយ៖** $720$។

**លំហាត់ ២៖** $A_6^{2}$។ **ដំណោះស្រាយ៖** $30$។

**លំហាត់ ៣៖** $C_6^{2}$។ **ដំណោះស្រាយ៖** $15$។

**លំហាត់ ៤៖** តម្រៀប $5$ មនុស្ស​ជា​ជួរ។ **ដំណោះស្រាយ៖** $120$។

**លំហាត់ ៥៖** ជ្រើស $2$ ក្នុង​ចំណោម $8$។ **ដំណោះស្រាយ៖** $28$។

**លំហាត់ ៦៖** $\\binom{10}{1}$។ **ដំណោះស្រាយ៖** $10$។

**លំហាត់ ៧៖** $\\binom{9}{9}$។ **ដំណោះស្រាយ៖** $1$។

**លំហាត់ ៨៖** $A_4^{4}$។ **ដំណោះស្រាយ៖** $24$។

**លំហាត់ ៩៖** $\\binom{8}{6}$។ **ដំណោះស្រាយ៖** $28$។

**លំហាត់ ១០៖** តើ​លំដាប់​សំខាន់​ក្នុង​គំបីណេហ្សុង​ឬ​ទេ? **ដំណោះស្រាយ៖** ទេ។

### ចំណុច​សំខាន់​ត្រូវ​ចង​ចាំ

- អារ៉ង់ស្ម៉ង់ (លំដាប់​សំខាន់)៖ $A_n^{k}=\\dfrac{n!}{(n-k)!}$។
- គំបីណេហ្សុង (លំដាប់​មិន​សំខាន់)៖ $C_n^{k}=\\dfrac{n!}{k!(n-k)!}$។
- $\\binom{n}{k}=\\binom{n}{n-k}$; ប្រើ​ក្នុង​បំណែងចែក​ទ្វេ។`,
