      content: `## ប្រូបាប​លក្ខខណ្ឌ

ប្រូបាប​នៃ $A$ ដោយ​ដឹង​ថា $B$ បាន​កើត៖

$$
P(A \\mid B) = \\frac{P(A \\cap B)}{P(B)} \\qquad (P(B) > 0)
$$

ដូច្នេះ $P(A \\cap B) = P(B)\\,P(A \\mid B)$។

## ព្រឹត្តិការណ៍​ឯករាជ្យ

$A$ និង $B$ **ឯករាជ្យ** បើ៖

$$
P(A \\cap B) = P(A)\\,P(B) \\quad\\Longleftrightarrow\\quad P(A \\mid B) = P(A)
$$

## រូបមន្ត​ប្រូបាប​សរុប

បើ $B_1, B_2, \\dots$ ជា​ការ​ចែក​លំហ៖ $P(A) = \\sum_i P(B_i)P(A \\mid B_i)$។

## ឧទាហរណ៍​ដោះស្រាយ

**ឧទាហរណ៍ ១៖** $P(A)=0.5, P(B)=0.4, P(A\\cap B)=0.2$។ $P(A\\mid B)=\\dfrac{0.2}{0.4}=0.5$។ ⟹ ឯករាជ្យ (ព្រោះ $=P(A)$)។

**ឧទាហរណ៍ ២៖** បោះ​កាក់​ពីរ​ដង៖ ប្រូបាប​ក្បាល​ទាំង​ពីរ ស្មើ $\\dfrac{1}{2}\\cdot\\dfrac{1}{2}=\\dfrac{1}{4}$ (ឯករាជ្យ)។

**ឧទាហរណ៍ ៣៖** គ្រាប់​ឡុកឡាក់ — ប្រូបាប​លេខ​គូ ដោយ​ដឹង​ថា​លេខ​ធំ​ជាង ៣៖ $\\dfrac{2/6}{3/6} = \\dfrac{2}{3}$ (ព្រោះ​លេខ​គូ​ធំ​ជាង ៣ គឺ $4, 6$)។

**ឧទាហរណ៍ ៤៖** $P(A)=0.6, P(B\\mid A)=0.5$៖ $P(A\\cap B)=0.3$។

**ឧទាហរណ៍ ៥៖** ថត​មាន​ក្រហម $3$ ខៀវ $2$។ ដក​ពីរ​ដោយ​គ្មាន​ដាក់​វិញ — ប្រូបាប​ក្រហម​ទាំង​ពីរ ស្មើ $\\dfrac{3}{5}\\cdot\\dfrac{2}{4}=\\dfrac{3}{10}$។

**ឧទាហរណ៍ ៦៖** តើ $A, B$ ឯករាជ្យ​បើ $P(A\\cap B)=P(A)P(B)$? បាទ។

**ឧទាហរណ៍ ៧៖** $P(A\\cup B)=P(A)+P(B)-P(A\\cap B)$។

**ឧទាហរណ៍ ៨៖** $P(\\bar A)=1-P(A)$។ បើ $P(A)=0.3$ ⟹ $0.7$។

## លំហាត់​អនុវត្ត

**លំហាត់ ១៖** $P(A\\cap B)=0.2, P(B)=0.5$។ $P(A\\mid B)$? **ដំណោះស្រាយ៖** $0.4$។

**លំហាត់ ២៖** កាក់​ពីរ​ដង៖ ប្រូបាប​ក្បាល​ទាំង​ពីរ? **ដំណោះស្រាយ៖** $\\frac{1}{4}$។

**លំហាត់ ៣៖** $P(A)=0.6, P(B\\mid A)=0.5$។ $P(A\\cap B)$? **ដំណោះស្រាយ៖** $0.3$។

**លំហាត់ ៤៖** $P(A)=0.3$។ $P(\\bar A)$? **ដំណោះស្រាយ៖** $0.7$។

**លំហាត់ ៥៖** គ្រាប់​ឡុកឡាក់៖ ប្រូបាប​លេខ​គូ ដោយ​ដឹង​ថា​ធំ​ជាង ៣? **ដំណោះស្រាយ៖** $\\frac{2}{3}$។

**លំហាត់ ៦៖** តើ​ឯករាជ្យ​បើ $P(A\\cap B)=P(A)P(B)$? **ដំណោះស្រាយ៖** បាទ។

**លំហាត់ ៧៖** ថត​ក្រហម​៣ ខៀវ​២៖ ប្រូបាប​ក្រហម​ទាំង​ពីរ (គ្មាន​ដាក់​វិញ)? **ដំណោះស្រាយ៖** $\\frac{3}{10}$។

**លំហាត់ ៨៖** $P(A)=0.4, P(B)=0.5$ ឯករាជ្យ។ $P(A\\cap B)$? **ដំណោះស្រាយ៖** $0.2$។

**លំហាត់ ៩៖** $P(A)=0.5, P(B)=0.3, P(A\\cap B)=0.1$។ $P(A\\cup B)$? **ដំណោះស្រាយ៖** $0.7$។

**លំហាត់ ១០៖** តើ $P(A\\mid B)=P(A)$ មាន​ន័យ​អ្វី? **ដំណោះស្រាយ៖** ឯករាជ្យ។

### ចំណុច​សំខាន់​ត្រូវ​ចង​ចាំ

- $P(A\\mid B)=\\dfrac{P(A\\cap B)}{P(B)}$។
- ឯករាជ្យ ⟺ $P(A\\cap B)=P(A)P(B)$។
- $P(A\\cup B)=P(A)+P(B)-P(A\\cap B)$; $P(\\bar A)=1-P(A)$។`,
