      minutes: 50,
      content: `## ភាព​ចែក​ដាច់

គេ​ថា $a$ **ចែក​ដាច់** $b$ (សរសេរ $a \\mid b$) បើ​មាន​ចំនួន​គត់ $k$ ដែល $b = a k$។ គេ​ក៏​និយាយ​ថា $b$ ជា​ពហុគុណ​នៃ $a$។

**ឧទាហរណ៍៖** $3 \\mid 12$ ព្រោះ $12 = 3 \\times 4$។ តែ $5 \\nmid 12$។

### លក្ខណៈ

- បើ $a \\mid b$ និង $a \\mid c$ នោះ $a \\mid (b + c)$ និង $a \\mid (b - c)$។
- បើ $a \\mid b$ នោះ $a \\mid k b$ សម្រាប់​គ្រប់​ចំនួន​គត់ $k$។
- បើ $a \\mid b$ និង $b \\mid c$ នោះ $a \\mid c$ (អន្តរកម្ម)។

## ការ​ចែក​អឺគ្លីត

សម្រាប់​ចំនួន​គត់ $a$ និង $b > 0$ មាន​គូ $(q, r)$ **តែ​មួយ​គត់** ដែល៖

$$
a = b q + r , \\qquad 0 \\le r < b
$$

ដែល $q$ ជា​ចំណិត និង $r$ ជា​សំណល់។ **ឧទាហរណ៍៖** $17 = 5 \\times 3 + 2$ ⟹ $q = 3$, $r = 2$។

$a \\mid b$ គឺ​ស្មើ​នឹង​ការ​ថា​សំណល់​នៃ​ការ​ចែក​ស្មើ $0$។

### លក្ខណៈ​វិនិច្ឆ័យ​ចែក​ដាច់

- ដោយ $2$៖ ខ្ទង់​ចុង​គូ។ ដោយ $5$៖ ខ្ទង់​ចុង $0$ ឬ $5$។
- ដោយ $3$ (ឬ $9$)៖ ផលបូក​ខ្ទង់​ចែក​ដាច់​ដោយ $3$ (ឬ $9$)។
- ដោយ $4$៖ ពីរ​ខ្ទង់​ចុង​ចែក​ដាច់​ដោយ $4$។

## ឧទាហរណ៍​ដោះស្រាយ

**ឧទាហរណ៍ ១៖** តើ $7 \\mid 91$? $91 = 7 \\times 13$ ⟹ បាទ។

**ឧទាហរណ៍ ២៖** ការ​ចែក​អឺគ្លីត​នៃ $23$ ដោយ $4$៖ $23 = 4 \\times 5 + 3$។

**ឧទាហរណ៍ ៣៖** សំណល់​នៃ $100$ ចែក $7$៖ $100 = 7 \\times 14 + 2$ ⟹ $r = 2$។

**ឧទាហរណ៍ ៤៖** តើ $258$ ចែក​ដាច់​ដោយ $3$? ផលបូក​ខ្ទង់ $2+5+8 = 15$ ចែក​ដាច់​ដោយ $3$ ⟹ បាទ។

**ឧទាហរណ៍ ៥៖** តើ $3 \\mid 12$ និង $3 \\mid 18$ ⟹ $3 \\mid 30$? បាទ ($12+18 = 30$)។

**ឧទាហរណ៍ ៦៖** ចំណិត និង​សំណល់​នៃ $45$ ចែក $6$៖ $45 = 6 \\times 7 + 3$។

**ឧទាហរណ៍ ៧៖** តើ $124$ ចែក​ដាច់​ដោយ $4$? ពីរ​ខ្ទង់​ចុង $24$ ចែក​ដាច់​ដោយ $4$ ⟹ បាទ។

**ឧទាហរណ៍ ៨៖** បើ $a \\mid 15$ តើ $a$ អាច​ជា​អ្វី​ខ្លះ (វិជ្ជមាន)? $1, 3, 5, 15$។

## លំហាត់​អនុវត្ត

**លំហាត់ ១៖** តើ $6 \\mid 84$? **ដំណោះស្រាយ៖** $84 = 6 \\times 14$ ⟹ បាទ។

**លំហាត់ ២៖** ចែក​អឺគ្លីត $37$ ដោយ $5$។ **ដំណោះស្រាយ៖** $37 = 5 \\times 7 + 2$។

**លំហាត់ ៣៖** សំណល់​នៃ $50$ ចែក $8$។ **ដំណោះស្រាយ៖** $50 = 8 \\times 6 + 2 \\Rightarrow r = 2$។

**លំហាត់ ៤៖** តើ $531$ ចែក​ដាច់​ដោយ $9$? **ដំណោះស្រាយ៖** $5+3+1 = 9$ ⟹ បាទ។

**លំហាត់ ៥៖** ចំណិត​នៃ $100$ ចែក $9$។ **ដំណោះស្រាយ៖** $q = 11$ ($r = 1$)។

**លំហាត់ ៦៖** តើ $2 \\mid 4$ និង $4 \\mid 20$ ⟹ $2 \\mid 20$? **ដំណោះស្រាយ៖** បាទ (អន្តរកម្ម)។

**លំហាត់ ៧៖** តើ $1000$ ចែក​ដាច់​ដោយ $4$? **ដំណោះស្រាយ៖** $00$ ⟹ បាទ។

**លំហាត់ ៨៖** កត្តា​វិជ្ជមាន​នៃ $12$។ **ដំណោះស្រាយ៖** $1,2,3,4,6,12$។

**លំហាត់ ៩៖** សំណល់​នៃ $77$ ចែក $10$។ **ដំណោះស្រាយ៖** $7$។

**លំហាត់ ១០៖** តើ $3 \\mid (12 + 9)$? **ដំណោះស្រាយ៖** $21 = 3 \\times 7$ ⟹ បាទ។

### ចំណុច​សំខាន់​ត្រូវ​ចង​ចាំ

- $a \\mid b \\iff b = ak$ (សំណល់ $= 0$)។
- ការ​ចែក​អឺគ្លីត៖ $a = bq + r$, $0 \\le r < b$ (តែ​មួយ​គត់)។
- លក្ខណៈ​វិនិច្ឆ័យ​ចែក​ដាច់​ដោយ $2, 3, 4, 5, 9$។`,
