      content: `## ពហុគុណ​រួម​តូច​បំផុត (LCM)

**LCM** នៃ $a$ និង $b$ (សរសេរ $\\operatorname{lcm}(a, b)$) ជា​ចំនួន​គត់​វិជ្ជមាន​តូច​បំផុត​ដែល​ជា​ពហុគុណ​នៃ​ទាំង $a$ និង $b$។

**ដោយ​ការ​ញែក៖** យក​កត្តា​បឋម​ទាំង​អស់​ដែល​មាន​ស្វ័យគុណ​ធំ​បំផុត។ ឧ. $\\operatorname{lcm}(12, 18)$៖ $2^{2}\\times 3^{2} = 36$។

## ទំនាក់ទំនង​សំខាន់

$$
\\gcd(a, b) \\times \\operatorname{lcm}(a, b) = a \\times b
$$

ដូច្នេះ $\\operatorname{lcm}(a, b) = \\dfrac{a \\times b}{\\gcd(a, b)}$។

## អនុវត្តន៍​សមភាព (congruence)

$a \\equiv b \\pmod{n}$ មាន​ន័យ​ថា $n \\mid (a - b)$។ ឧ. $17 \\equiv 2 \\pmod{5}$។

**ឧទាហរណ៍​ជាក់ស្តែង៖** LCM ប្រើ​រក​ពេល​ដែល​ព្រឹត្តិការណ៍​វិល​ជុំ​ពីរ​ជួប​គ្នា​ម្តង​ទៀត។

## ឧទាហរណ៍​ដោះស្រាយ

**ឧទាហរណ៍ ១៖** $\\operatorname{lcm}(4, 6)$៖ $\\dfrac{4\\times 6}{\\gcd(4,6)} = \\dfrac{24}{2} = 12$។

**ឧទាហរណ៍ ២៖** $\\operatorname{lcm}(12, 18) = \\dfrac{216}{6} = 36$។

**ឧទាហរណ៍ ៣៖** $\\operatorname{lcm}(5, 7) = 35$ (បឋម​រវាង​គ្នា ⟹ ផលគុណ)។

**ឧទាហរណ៍ ៤៖** បើ $\\gcd = 4$ និង $\\operatorname{lcm} = 24$ តើ $a\\times b$? $4\\times 24 = 96$។

**ឧទាហរណ៍ ៥៖** $\\operatorname{lcm}(8, 12)$៖ $\\dfrac{96}{4} = 24$។

**ឧទាហរណ៍ ៦៖** $23 \\pmod 5$៖ $23 = 5\\times 4 + 3 \\Rightarrow 23 \\equiv 3 \\pmod 5$។

**ឧទាហរណ៍ ៧៖** រថភ្លើង​មក​រៀង​រាល់ $12$ និង $18$ នាទី។ ជួប​គ្នា​រៀង​រាល់ $\\operatorname{lcm}(12,18) = 36$ នាទី។

**ឧទាហរណ៍ ៨៖** $\\operatorname{lcm}(6, 10) = \\dfrac{60}{2} = 30$។

## លំហាត់​អនុវត្ត

**លំហាត់ ១៖** $\\operatorname{lcm}(4, 6)$។ **ដំណោះស្រាយ៖** $12$។

**លំហាត់ ២៖** $\\operatorname{lcm}(9, 12)$។ **ដំណោះស្រាយ៖** $36$។

**លំហាត់ ៣៖** $\\operatorname{lcm}(5, 8)$។ **ដំណោះស្រាយ៖** $40$។

**លំហាត់ ៤៖** បើ $\\gcd(a,b)=3$, $\\operatorname{lcm}=30$ តើ $ab$? **ដំណោះស្រាយ៖** $90$។

**លំហាត់ ៥៖** $\\operatorname{lcm}(15, 20)$។ **ដំណោះស្រាយ៖** $60$។

**លំហាត់ ៦៖** $37 \\pmod 6$។ **ដំណោះស្រាយ៖** $1$។

**លំហាត់ ៧៖** $\\operatorname{lcm}(7, 14)$។ **ដំណោះស្រាយ៖** $14$។

**លំហាត់ ៨៖** $\\operatorname{lcm}(3, 5, 6)$។ **ដំណោះស្រាយ៖** $30$។

**លំហាត់ ៩៖** តើ $20 \\equiv 2 \\pmod 6$? **ដំណោះស្រាយ៖** $20-2=18 = 6\\times 3$ ⟹ បាទ។

**លំហាត់ ១០៖** $\\operatorname{lcm}(10, 25)$។ **ដំណោះស្រាយ៖** $50$។

### ចំណុច​សំខាន់​ត្រូវ​ចង​ចាំ

- $\\operatorname{lcm}(a,b) = \\dfrac{ab}{\\gcd(a,b)}$។
- បឋម​រវាង​គ្នា ⟹ $\\operatorname{lcm} = ab$។
- $a \\equiv b \\pmod n \\iff n \\mid (a-b)$។`,
