      slug: 'adv-parametric-derivative',
      minutes: 50,
      content: `## មេគុណ​ប្រាប់​ទិស​នៃ​បន្ទាត់​ប៉ះ

សម្រាប់​ខ្សែកោង​ប៉ារ៉ាម៉ែត្រ $x = f(t)$, $y = g(t)$ មេគុណ​ប្រាប់​ទិស​នៃ​បន្ទាត់​ប៉ះ​គឺ៖

$$
\\frac{dy}{dx} = \\frac{dy/dt}{dx/dt} \\qquad (dx/dt \\ne 0)
$$

**ឧទាហរណ៍​គំរូ៖** $x = t^{2}$, $y = t^{3}$។ $\\dfrac{dx}{dt} = 2t$, $\\dfrac{dy}{dt} = 3t^{2}$៖

$$
\\frac{dy}{dx} = \\frac{3t^{2}}{2t} = \\frac{3t}{2}
$$

## បន្ទាត់​ប៉ះ​ផ្ដេក និង​ឈរ

- **ផ្ដេក**៖ $\\dfrac{dy}{dt} = 0$ (និង $\\dfrac{dx}{dt} \\ne 0$)។
- **ឈរ**៖ $\\dfrac{dx}{dt} = 0$ (និង $\\dfrac{dy}{dt} \\ne 0$)។

## ឧទាហរណ៍​ដោះស្រាយ

**ឧទាហរណ៍ ១៖** $x = t$, $y = t^{2}$។ $\\dfrac{dy}{dx} = \\dfrac{2t}{1} = 2t$។

**ឧទាហរណ៍ ២៖** នៅ $t = 1$ សម្រាប់​ខាង​លើ៖ $\\dfrac{dy}{dx} = 2$។

**ឧទាហរណ៍ ៣៖** $x = \\cos t$, $y = \\sin t$។ $\\dfrac{dy}{dx} = \\dfrac{\\cos t}{-\\sin t} = -\\cot t$។

**ឧទាហរណ៍ ៤៖** $x = 2t + 1$, $y = 3t$។ $\\dfrac{dy}{dx} = \\dfrac{3}{2}$ (បន្ទាត់)។

**ឧទាហរណ៍ ៥៖** បន្ទាត់​ប៉ះ​ផ្ដេក​សម្រាប់ $x = t, y = t^{2} - 4t$៖ $\\dfrac{dy}{dt} = 2t - 4 = 0 \\Rightarrow t = 2$។

**ឧទាហរណ៍ ៦៖** $x = t^{3}$, $y = t^{2}$។ $\\dfrac{dy}{dx} = \\dfrac{2t}{3t^{2}} = \\dfrac{2}{3t}$។

**ឧទាហរណ៍ ៧៖** បន្ទាត់​ប៉ះ​ឈរ​សម្រាប់ $x = t^{2} - 1, y = t$៖ $\\dfrac{dx}{dt} = 2t = 0 \\Rightarrow t = 0$។

**ឧទាហរណ៍ ៨៖** នៅ $t = 2$ សម្រាប់ $x = t^{2}, y = t^{3}$៖ $\\dfrac{dy}{dx} = \\dfrac{3t}{2} = 3$។

## លំហាត់​អនុវត្ត

**លំហាត់ ១៖** $\\dfrac{dy}{dx}$ សម្រាប់ $x = t, y = t^{3}$។ **ដំណោះស្រាយ៖** $3t^{2}$។

**លំហាត់ ២៖** នៅ $t = 1$៖ $x = t, y = t^{2}$។ **ដំណោះស្រាយ៖** $2$។

**លំហាត់ ៣៖** $\\dfrac{dy}{dx}$ សម្រាប់ $x = 3t, y = 6t$។ **ដំណោះស្រាយ៖** $2$។

**លំហាត់ ៤៖** បន្ទាត់​ប៉ះ​ផ្ដេក៖ $x = t, y = t^{2} - 6t$។ **ដំណោះស្រាយ៖** $t = 3$។

**លំហាត់ ៥៖** $\\dfrac{dy}{dx}$ សម្រាប់ $x = t^{2}, y = t^{4}$។ **ដំណោះស្រាយ៖** $\\frac{4t^{3}}{2t} = 2t^{2}$។

**លំហាត់ ៦៖** នៅ $t = 2$៖ $x = t^{2}, y = t^{3}$។ **ដំណោះស្រាយ៖** $3$។

**លំហាត់ ៧៖** បន្ទាត់​ប៉ះ​ឈរ៖ $x = t^{2}, y = t$។ **ដំណោះស្រាយ៖** $t = 0$។

**លំហាត់ ៨៖** $\\dfrac{dy}{dx}$ សម្រាប់ $x = \\sin t, y = \\cos t$។ **ដំណោះស្រាយ៖** $-\\tan t$។

**លំហាត់ ៩៖** $\\dfrac{dy}{dx}$ សម្រាប់ $x = 2t, y = t^{2}$។ **ដំណោះស្រាយ៖** $t$។

**លំហាត់ ១០៖** នៅ $t = 3$៖ $x = t, y = t^{2}$។ **ដំណោះស្រាយ៖** $6$។

### ចំណុច​សំខាន់​ត្រូវ​ចង​ចាំ

- $\\dfrac{dy}{dx} = \\dfrac{dy/dt}{dx/dt}$។
- ផ្ដេក៖ $dy/dt = 0$; ឈរ៖ $dx/dt = 0$។
- ជំនួស $t$ ដើម្បី​រក​មេគុណ​នៅ​ចំណុច​ជាក់លាក់។`,
