      minutes: 50,
      content: `## បូក ដក គុណ

$$
(a+bi)+(c+di) = (a+c)+(b+d)i , \\qquad (a+bi)(c+di) = (ac-bd)+(ad+bc)i
$$

(ចាត់ទុក $i$ ជា​អថេរ រួច​ជំនួស $i^{2}=-1$។)

## ចំនួន​ឆ្លាស់ (conjugué)

$$
\\bar{z} = a - bi
$$

លក្ខណៈ៖ $z + \\bar{z} = 2a$ (ពិត); $z\\bar{z} = a^{2}+b^{2}$ (ពិត​វិជ្ជមាន); $\\overline{z_1 z_2} = \\bar{z_1}\\,\\bar{z_2}$។

## ចែក

គុណ​ភាគយក​និង​ភាគបែង​ដោយ​ឆ្លាស់​នៃ​ភាគបែង៖

$$
\\frac{z_1}{z_2} = \\frac{z_1 \\bar{z_2}}{z_2 \\bar{z_2}} = \\frac{z_1 \\bar{z_2}}{|z_2|^{2}}
$$

## ម៉ូឌុល

$$
|z| = \\sqrt{a^{2} + b^{2}} = \\sqrt{z\\bar{z}}
$$

លក្ខណៈ៖ $|z_1 z_2| = |z_1||z_2|$; $\\left|\\dfrac{z_1}{z_2}\\right| = \\dfrac{|z_1|}{|z_2|}$។

## ឧទាហរណ៍​ដោះស្រាយ

**ឧទាហរណ៍ ១៖** $(3+2i)+(1-4i) = 4 - 2i$។

**ឧទាហរណ៍ ២៖** $(3+2i)(1-4i) = 3 - 12i + 2i - 8i^{2} = 11 - 10i$។

**ឧទាហរណ៍ ៣៖** ឆ្លាស់​នៃ $5 - 3i$៖ $5 + 3i$។

**ឧទាហរណ៍ ៤៖** $|3 + 4i| = \\sqrt{9+16} = 5$។

**ឧទាហរណ៍ ៥៖** $\\dfrac{1}{i} = \\dfrac{-i}{i(-i)} = \\dfrac{-i}{1} = -i$។

**ឧទាហរណ៍ ៦៖** $\\dfrac{2+i}{1-i} = \\dfrac{(2+i)(1+i)}{2} = \\dfrac{1 + 3i}{2}$។

**ឧទាហរណ៍ ៧៖** $z\\bar{z}$ សម្រាប់ $z = 2 + 3i$៖ $4 + 9 = 13$។

**ឧទាហរណ៍ ៨៖** $|(1+i)(1-i)| = |2| = 2$។

## លំហាត់​អនុវត្ត

**លំហាត់ ១៖** $(2+i)+(3-4i)$។ **ដំណោះស្រាយ៖** $5 - 3i$។

**លំហាត់ ២៖** $(1+i)(1-i)$។ **ដំណោះស្រាយ៖** $2$។

**លំហាត់ ៣៖** ឆ្លាស់​នៃ $-2 + 5i$។ **ដំណោះស្រាយ៖** $-2 - 5i$។

**លំហាត់ ៤៖** $|5 + 12i|$។ **ដំណោះស្រាយ៖** $13$។

**លំហាត់ ៥៖** $(2+3i)^{2}$។ **ដំណោះស្រាយ៖** $-5 + 12i$។

**លំហាត់ ៦៖** $\\dfrac{1}{2+i}$។ **ដំណោះស្រាយ៖** $\\dfrac{2-i}{5}$។

**លំហាត់ ៧៖** $z\\bar{z}$ សម្រាប់ $z=1+i$។ **ដំណោះស្រាយ៖** $2$។

**លំហាត់ ៨៖** $|3i|$។ **ដំណោះស្រាយ៖** $3$។

**លំហាត់ ៩៖** $(4-i)-(2+3i)$។ **ដំណោះស្រាយ៖** $2 - 4i$។

**លំហាត់ ១០៖** $i(2 - i)$។ **ដំណោះស្រាយ៖** $1 + 2i$។

### ចំណុច​សំខាន់​ត្រូវ​ចង​ចាំ

- គុណ៖ ជំនួស $i^{2}=-1$។
- ចែក៖ គុណ​ដោយ​ឆ្លាស់​នៃ​ភាគបែង។
- $|z| = \\sqrt{a^{2}+b^{2}}$; $z\\bar{z} = |z|^{2}$។`,
