      minutes: 55,
      content: `## ម៉ូឌុល និង​អាគុយម៉ង់

សម្រាប់ $z = a + bi \\ne 0$៖ ម៉ូឌុល $r = |z| = \\sqrt{a^{2}+b^{2}}$ និង **អាគុយម៉ង់** $\\theta = \\arg(z)$ ដែល៖

$$
\\cos\\theta = \\frac{a}{r} , \\qquad \\sin\\theta = \\frac{b}{r}
$$

## ទម្រង់​ត្រីកោណមាត្រ

$$
z = r(\\cos\\theta + i\\sin\\theta)
$$

## ទម្រង់​អ៊ិចស្ប៉ូណង់ស្យែល (Euler)

$$
e^{i\\theta} = \\cos\\theta + i\\sin\\theta \\;\\Longrightarrow\\; z = r\\,e^{i\\theta}
$$

\`\`\`graph
{
  "xRange": [-1, 3],
  "yRange": [-1, 3],
  "xLabel": "Re",
  "yLabel": "Im",
  "segments": [
    { "from": [0, 0], "to": [1, 1.732], "color": "violet", "arrow": true, "label": "r=2" }
  ],
  "points": [{ "x": 1, "y": 1.732, "label": "z=1+i√3", "color": "rose" }],
  "caption": "z=1+i√3 = 2(cos π/3 + i sin π/3) = 2e^(iπ/3) — r=2, θ=π/3"
}
\`\`\`

## គុណ និង​ចែក (ទម្រង់​ប៉ូឡែ)

$$
z_1 z_2 = r_1 r_2\\,e^{i(\\theta_1 + \\theta_2)} , \\qquad \\frac{z_1}{z_2} = \\frac{r_1}{r_2}\\,e^{i(\\theta_1 - \\theta_2)}
$$

គុណ ⟹ ម៉ូឌុល​គុណ​គ្នា អាគុយម៉ង់​បូក​គ្នា។

## ឧទាហរណ៍​ដោះស្រាយ

**ឧទាហរណ៍ ១៖** $z = 1 + i\\sqrt{3}$៖ $r = 2$, $\\theta = \\dfrac{\\pi}{3}$ ⟹ $2e^{i\\pi/3}$។

**ឧទាហរណ៍ ២៖** $z = 1 + i$៖ $r = \\sqrt{2}$, $\\theta = \\dfrac{\\pi}{4}$។

**ឧទាហរណ៍ ៣៖** $z = i$៖ $r = 1$, $\\theta = \\dfrac{\\pi}{2}$ ⟹ $e^{i\\pi/2}$។

**ឧទាហរណ៍ ៤៖** $|z| = 2, \\arg z = 0$ ⟹ $z = 2$។

**ឧទាហរណ៍ ៥៖** $e^{i\\pi} = -1$ (អត្តសញ្ញាណ Euler)។

**ឧទាហរណ៍ ៦៖** $z = -1$៖ $r = 1$, $\\theta = \\pi$។

**ឧទាហរណ៍ ៧៖** គុណ $2e^{i\\pi/6} \\cdot 3e^{i\\pi/3} = 6e^{i\\pi/2} = 6i$។

**ឧទាហរណ៍ ៨៖** $z = 2\\left(\\cos\\dfrac{\\pi}{2} + i\\sin\\dfrac{\\pi}{2}\\right) = 2i$។

## លំហាត់​អនុវត្ត

**លំហាត់ ១៖** ម៉ូឌុល​នៃ $1 + i$។ **ដំណោះស្រាយ៖** $\\sqrt{2}$។

**លំហាត់ ២៖** អាគុយម៉ង់​នៃ $i$។ **ដំណោះស្រាយ៖** $\\frac{\\pi}{2}$។

**លំហាត់ ៣៖** ទម្រង់​អ៊ិចស្ប៉ូ​នៃ $z=2, \\arg=0$។ **ដំណោះស្រាយ៖** $2e^{i0}=2$។

**លំហាត់ ៤៖** $e^{i\\pi}$។ **ដំណោះស្រាយ៖** $-1$។

**លំហាត់ ៥៖** អាគុយម៉ង់​នៃ $-1$។ **ដំណោះស្រាយ៖** $\\pi$។

**លំហាត់ ៦៖** $z = 3e^{i\\pi/2}$ ជា​ទម្រង់​ពិជគណិត។ **ដំណោះស្រាយ៖** $3i$។

**លំហាត់ ៧៖** ម៉ូឌុល​នៃ $\\sqrt{3}+i$។ **ដំណោះស្រាយ៖** $2$។

**លំហាត់ ៨៖** គុណ $2e^{i\\pi/4}\\cdot 2e^{i\\pi/4}$។ **ដំណោះស្រាយ៖** $4e^{i\\pi/2}=4i$។

**លំហាត់ ៩៖** អាគុយម៉ង់​នៃ $1+i\\sqrt{3}$។ **ដំណោះស្រាយ៖** $\\frac{\\pi}{3}$។

**លំហាត់ ១០៖** $e^{i\\cdot 0}$។ **ដំណោះស្រាយ៖** $1$។

### ចំណុច​សំខាន់​ត្រូវ​ចង​ចាំ

- $z = r(\\cos\\theta + i\\sin\\theta) = re^{i\\theta}$។
- គុណ ⟹ ម៉ូឌុល​គុណ អាគុយម៉ង់​បូក។
- $e^{i\\pi} = -1$; $e^{i\\pi/2} = i$។`,
